 const p=G.pk(P),arr=G.r(0,23)*60+G.pk([0,10,15,20,30,40,45,50]),fl=G.r(3,13)*60+G.pk([0,15,20,30,40,45]);
 const ok=arr-p[1]-fl;const o=G.opt(G.hm(ok),[G.hm(arr-fl),G.hm(arr+p[1]-fl),G.hm(ok+30),G.hm(ok-60)]);
