{const o=fwView;fwView=function(){let s=o.apply(this,arguments);const F=V.fly;if(!F||F.free||F.stage!=='fly'||!F.xq)return s;const add=(F.xq.cur?xqHTML():'')+xqChip();const k=s.lastIndexOf('</div>');return k<0?s+add:s.slice(0,k)+add+s.slice(k)}}
{const o=fwBusy;fwBusy=function(){const F=V.fly;if(F&&F.xq&&F.xq.cur)return true;return o.apply(this,arguments)}}
