{const o=flyFinish;flyFinish=function(){const F=V.fly,X=F&&F.xq;const r=o.apply(this,arguments);try{if(X&&F.res){const S1=xqSave();S1.fl++;F.res.xq={res:X.res,n:X.n,done:X.p,all:X.L.length};save();render()}}catch(e){}return r}}
{const o=flyReport;flyReport=function(){let s=o.apply(this,arguments);const R=V.fly&&V.fly.res;if(!R||!R.xq)return s;const S1=xqSave();
 const h=`<div class="xq-rep"><h3>ข้อสอบระหว่างบิน</h3><div class="xq-rg">${XQ_ORD.map(k=>{const a=R.xq.res[k],P=S1[k];return `<div><span class="xq-tg xq-${k}">${XQS[k][0]}</span><small>${XQS[k][1]}</small><b>${a[0]}<i>/${a[1]}</i></b><em>สะสม ${P.n?Math.round(P.ok/P.n*100):0}% จาก ${P.n} ข้อ</em></div>`}).join('')}</div>${R.xq.done<R.xq.all?`<p class="xq-rn">ทำไป ${R.xq.done} จาก ${R.xq.all} ข้อ</p>`:''}</div>`;
 const k=s.indexOf('</section>');return k<0?s+h:s.slice(0,k)+h+s.slice(k)}}
